import { IS_WEB_APP } from "./Platform";

type CapacitorBridge = { isNativePlatform?: () => boolean };

// The GitHub Pages web app only: the offline cache (sw.js is generated by
// scripts/webapp.ts), and a request that the browser never evicts the saved games, which
// live in localStorage. The native apps' web views and the Vercel website get neither.
export const initWebApp = () => {
	if (!import.meta.env.PROD || !IS_WEB_APP || !("serviceWorker" in navigator))
		return;
	const capacitor = (window as { Capacitor?: CapacitorBridge }).Capacitor;
	if (capacitor?.isNativePlatform?.()) return;
	window.addEventListener("load", () => {
		navigator.serviceWorker.register("./sw.js").catch(() => {});
	});
	navigator.storage?.persist?.().catch(() => {});
};
